+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        email.setPattern(EMAIL.pattern());
+        send.addClickListener(e -> submit());
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER);
+
+        for (var field : List.of(name, email, phone, message)) {
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            field.addValueChangeListener(e -> {
+                field.setInvalid(false);
+                send.setEnabled(true);
+            });
+        }
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setAllRowsVisible(true);
+        refreshGrid();
+
+        leaveDialog.setHeaderTitle("Unsent message");
+        leaveDialog.add("Discard what you have typed?");
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+        leaveDialog.getFooter().add(
+                new Button("Keep editing", e -> {
+                    leaveDialog.close();
+                    pendingNavigation.cancel();
+                }),
+                new Button("Discard", e -> {
+                    leaveDialog.close();
+                    pendingNavigation.proceed();
+                }));
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), name, email, phone, message, send, grid,
+                leaveDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private void submit() {
+        if (!send.isEnabled() || !validate()) {
+            return;
+        }
+        messages.save(new ContactMessage(name.getValue().strip(), email.getValue().strip(),
+                phone.getValue().strip(), message.getValue().strip()));
+        refreshGrid();
+        Notification.show("Message sent");
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing the fields re-enables Send through the edit listeners, so disable it last.
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        String nameError = name.getValue().isBlank() ? "Name is required" : null;
+        String emailError = emailError();
+        String messageError = messageError();
+
+        name.setErrorMessage(nameError);
+        name.setInvalid(nameError != null);
+        email.setErrorMessage(emailError);
+        email.setInvalid(emailError != null);
+        message.setErrorMessage(messageError);
+        message.setInvalid(messageError != null);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private String emailError() {
+        String address = email.getValue().strip();
+        if (!address.isEmpty()) {
+            return EMAIL.matcher(address).matches() ? null : "Enter a valid e-mail address";
+        }
+        return phone.getValue().isBlank() ? "Give an e-mail address or a phone number" : null;
+    }
+
+    private String messageError() {
+        String text = message.getValue().strip();
+        if (text.isEmpty()) {
+            return "Message is required";
+        }
+        if (text.codePointCount(0, text.length()) > MAX_MESSAGE_LENGTH) {
+            return "Message must be at most 500 characters";
+        }
+        return null;
+    }
+
+    private boolean hasInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messages.findAll());
+    }
+}
